  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Aetherfall — a high-definition pixel-art open-world action RPG.",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3000",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3000"
  },
  "dependencies": {
    "@fontsource/press-start-2p": "^5.3.0",
