/* ─────────────────────────────────────────────────────────────
   AETHERFALL — pixelbound interface
   ───────────────────────────────────────────────────────────── */
@import '@fontsource/press-start-2p/400.css';
@import '@fontsource/vt323/400.css';

:root {
  color-scheme: dark;
  --ink: #071018;
  --ink-2: #0d1a22;
  --ink-3: #142731;
  --paper: #f1e3bf;
  --paper-dim: #c7b892;
  --gold: #e9b85f;
  --gold-hot: #ffd88a;
  --gold-deep: #9b6b2d;
  --mint: #71d7c4;
  --mint-deep: #286f6b;
  --blood: #d85a57;
  --violet: #9b84dd;
  --line: rgba(232, 206, 151, 0.26);
  --line-bright: rgba(240, 215, 158, 0.62);
  --shadow: rgba(0, 0, 0, 0.72);
  --pixel: 'Press Start 2P', monospace;
  --body: 'VT323', monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #050b0f; }
body {
  font-family: var(--body);
  font-size: 19px;
  color: var(--paper);
  -webkit-font-smoothing: none;
  text-rendering: geometricPrecision;
  touch-action: none;
  user-select: none;
  overscroll-behavior: none;
}
button, input { font: inherit; color: inherit; }
button { cursor: pointer; -webkit-tap-highlight-color: transparent; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--gold-hot); outline-offset: 3px; }
[hidden], .hidden { display: none !important; }
::selection { background: var(--gold); color: var(--ink); }

#game, #viewport { position: fixed; inset: 0; width: 100%; height: 100%; }
#viewport canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  filter: saturate(1.06) contrast(1.04);
}
#viewport::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(8, 19, 28, 0.07), transparent 32%, transparent 68%, rgba(3, 8, 11, 0.32));
}
#atmosphere { position: fixed; inset: 0; pointer-events: none; z-index: 3; }
.vignette {
  position: absolute; inset: 0;
  box-shadow: inset 0 0 130px 30px rgba(2, 6, 9, 0.82), inset 0 0 40px 2px rgba(2, 6, 9, 0.6);
}
.scanlines {
  position: absolute; inset: 0; opacity: 0.08;
  background: repeating-linear-gradient(0deg, transparent 0 2px, #000 2px 3px);
  mix-blend-mode: multiply;
}
#weather-tint { position: absolute; inset: 0; transition: background 1.5s ease, opacity 1.2s ease; }
#rain-glass {
  position: absolute; inset: 0; opacity: 0; transition: opacity 1s ease;
  background:
    radial-gradient(ellipse at 20% 10%, transparent 0 5px, rgba(170, 215, 220, 0.09) 6px, transparent 8px),
    radial-gradient(ellipse at 80% 30%, transparent 0 9px, rgba(170, 215, 220, 0.08) 10px, transparent 12px),
    radial-gradient(ellipse at 40% 76%, transparent 0 7px, rgba(170, 215, 220, 0.07) 8px, transparent 10px);
  background-size: 320px 280px, 420px 360px, 280px 220px;
  mix-blend-mode: screen;
}
#rain-glass.active { opacity: .7; animation: glassDrift 8s linear infinite; }
@keyframes glassDrift { to { background-position: 22px 280px, -25px 360px, 17px 220px; } }
#damage-flash {
  position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(circle, transparent 42%, rgba(145, 18, 20, 0.72) 100%);
  transition: opacity .12s ease-out;
}
#damage-flash.flash { opacity: 1; transition: none; }

/* ── shared pixel pieces ───────────────────────────────────── */
.pixel-button {
  position: relative;
  padding: 12px 20px;
  border: 1px solid var(--line-bright);
  background: linear-gradient(180deg, #243b43, #122630);
  color: var(--paper);
  font-family: var(--pixel);
  font-size: 9px;
  line-height: 1.6;
  text-transform: uppercase;
  box-shadow: 3px 3px 0 #050b0f, inset 0 1px 0 rgba(255,255,255,.12);
  transition: transform .12s, background .15s, color .15s;
}
.pixel-button:hover { transform: translate(-1px, -1px); background: linear-gradient(180deg, #34545e, #192f39); box-shadow: 4px 4px 0 #050b0f; }
.pixel-button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #050b0f; }
.pixel-button.gold { background: linear-gradient(180deg, var(--gold-hot), var(--gold) 52%, #b47c31); color: #1c1204; border-color: #ffe8ae; }
.pixel-button.gold:hover { background: linear-gradient(180deg, #fff0c4, var(--gold-hot) 50%, #c88d3d); }
.pixel-button.muted { color: var(--paper-dim); background: #101a20; }
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 19px; padding: 2px 5px;
  font-family: var(--pixel); font-size: 7px; color: var(--paper);
  border: 1px solid rgba(241, 227, 191, .32);
  background: rgba(5, 13, 18, .7);
  box-shadow: 0 2px 0 rgba(0,0,0,.4);
}

/* ── HUD ───────────────────────────────────────────────────── */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#hud button, #hud canvas { pointer-events: auto; }
.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: grid; grid-template-columns: minmax(330px, 390px) 1fr minmax(280px, 330px);
  gap: 18px; align-items: start;
  padding: max(18px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) 0 max(20px, env(safe-area-inset-left));
  background: linear-gradient(180deg, rgba(5, 12, 16, .72), transparent);
}
.hero-card {
  display: flex; gap: 13px;
  padding: 10px 12px 11px;
