.hero-line span { font-size: 16px; line-height: 1; color: var(--paper-dim); white-space: nowrap; }
.meter { position: relative; height: 13px; margin: 4px 0; background: #071016; border: 1px solid rgba(0,0,0,.65); box-shadow: inset 0 2px 3px rgba(0,0,0,.6); overflow: hidden; }
.meter::after { content:''; position:absolute; inset:0; background: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0,0,0,.18) calc(10% - 1px) 10%); pointer-events:none; }
.meter-fill { height: 100%; width: 100%; transition: width .28s ease-out; position: relative; }
