.energy-meter { height: 9px; }
.energy-meter .meter-fill { background: linear-gradient(180deg, #7ce2da, #2f959b 55%, #1c5b70); }
.meter-label { position: absolute; inset: 0 5px 0 5px; display: flex; align-items: center; justify-content: space-between; font-size: 13px; line-height: 1; text-shadow: 0 1px 1px #000; }
