.xp-line { display: flex; align-items: center; gap: 5px; margin-top: 5px; font-family: var(--pixel); font-size: 5px; color: var(--paper-dim); }
.xp-track { flex: 1; height: 3px; background: #061015; border: 1px solid rgba(255,255,255,.08); }
#xp-fill { width: 0%; height: 100%; background: var(--gold); box-shadow: 0 0 6px rgba(233,184,95,.7); transition: width .3s; }
