#zone-name { color: var(--gold-hot); }
#biome-name { font-family: var(--body); font-size: 16px; letter-spacing: .5px; color: var(--paper-dim); }
.ribbon-dot { font-size: 6px; color: var(--gold); }
.world-time { display: inline-flex; align-items: center; gap: 8px; margin-top: 4px; font-size: 16px; color: rgba(241,227,191,.64); }
