}
.tracker-title { display: flex; justify-content: space-between; align-items: center; padding: 7px 9px; border-bottom: 1px solid var(--line); }
.tracker-title span { font-family: var(--pixel); font-size: 6px; letter-spacing: 1.4px; color: var(--gold); }
.tracker-title button { width: 20px; height: 18px; padding: 0; font-family: var(--pixel); font-size: 6px; border: 1px solid var(--line); background: #0a161d; color: var(--paper-dim); }
#quest-tracker-list { padding: 2px 9px; }
.quest-track { padding: 6px 0 5px; }
.quest-track + .quest-track { border-top: 1px dashed rgba(232,206,151,.14); }
.quest-track .q-name { display: flex; align-items: flex-start; gap: 6px; font-size: 17px; line-height: 1.05; color: #fff0c8; }
.quest-track .q-mark { color: var(--gold); font-family: var(--pixel); font-size: 7px; margin-top: 2px; }
