const RARITY_LEVEL_OFFSET = { common: 0, uncommon: 1, rare: 2, epic: 3, legendary: 4 };

let itemUid = 1;

export function makeItem(template, level = 1, options = {}) {
  const lvl = Math.max(1, Math.round(level));
  const rarityId = options.rarity || template.rarity || 'common';
  const rarity = RARITIES[rarityId] || RARITIES.common;
  const scale = 1 + (lvl - 1) * 0.245;
  const isWeapon = !!template.base;
  const item = {
    uid: options.uid || `item_${itemUid++}`,
    templateId: template.id,
    name: template.name,
    icon: options.icon || (isWeapon ? (WEAPON_ICONS[options.classId] || '⚔') : '❖'),
    type: isWeapon ? 'weapon' : 'armor',
    slot: isWeapon ? 'weapon' : 'armor',
    element: template.element || 'physical',
    rarity: rarityId,
    level: lvl,
    desc: template.desc || 'A relic of the Sundered Realms.',
    classId: options.classId || null,
    price: Math.round((isWeapon ? 48 : 40) * rarity.mult + lvl * (isWeapon ? 16 : 14) * rarity.mult),
    damage: isWeapon ? Math.round((template.base + lvl * 2.1) * rarity.mult) : 0,
    elementPower: isWeapon ? Math.round((template.base * 0.33 + lvl * 0.8) * rarity.mult) : 0,
    health: template.health ? Math.round(template.health * (1 + (lvl - 1) * 0.16) * rarity.mult) : 0,
    armor: template.armor ? Math.round(template.armor * (1 + (lvl - 1) * 0.14) * rarity.mult) : 0,
    crit: 0,
    power: isWeapon ? 0 : Math.round((2 + lvl * 0.45) * rarity.mult),
    resist: template.element && template.element !== 'physical' ? { [template.element]: 0.05 + rarity.mult * 0.015 } : {},
    trinket: false,
  };
  return item;
}

export function makeTrinket(template, level = 1) {
  const rarity = RARITIES[template.rarity] || RARITIES.rare;
  const scale = 1 + (Math.max(1, level) - 1) * 0.18;
  return {
    uid: `item_${itemUid++}`,
    templateId: template.id,
    name: template.name,
    icon: template.icon,
    type: 'trinket',
    slot: 'trinket',
    element: template.element || 'physical',
    rarity: template.rarity,
    level: Math.max(1, Math.round(level)),
    desc: template.desc,
    price: Math.round(template.price * scale),
    classId: null,
    damage: 0,
    elementPower: Math.round((template.elementPower || 0) * scale),
    health: Math.round((template.health || 0) * scale),
    armor: 0,
    power: Math.round((template.power || 0) * scale),
    crit: template.crit || 0,
    lifesteal: template.lifesteal || 0,
    resist: template.resist || {},
    trinket: true,
  };
}

export function makeStarterWeapon(classId) {
  const gear = CLASS_GEAR[classId];
  const tpl = gear.weapons[0];
  const item = makeItem(tpl, 1, { classId, rarity: 'common' });
  item.name = tpl.name;
  item.damage = Math.round(tpl.base + 2);
  item.elementPower = 0;
  item.price = 12;
  item.desc = tpl.desc;
  return item;
}

export function makeStarterArmor(classId) {
  const gear = CLASS_GEAR[classId];
  const tpl = gear.armor[0];
  const item = makeItem(tpl, 1, { classId, rarity: 'common' });
  return item;
}

export function makeQuestRelic(classId, level) {
  const gear = CLASS_GEAR[classId];
  const idx = Math.min(gear.weapons.length - 1, 2 + Math.floor(level / 5));
  const tpl = gear.weapons[idx];
  return makeItem(tpl, Math.max(3, level + 1), { classId, rarity: idx >= 3 ? 'epic' : 'rare' });
}

export function generateShopStock(type, player, vendorLevel = 1) {
  const level = Math.max(1, player.level + (vendorLevel >= 5 ? 1 : 0));
  const stock = [];
  const gear = CLASS_GEAR[player.classId];
  if (type === 'weapon') {
    const available = gear.weapons.filter(t => {
      const req = RARITY_LEVEL_OFFSET[t.rarity] * 3 + 1;
      return req <= level + 2;
    });
    const start = Math.max(0, Math.min(available.length - 3, Math.floor((level - 1) / 4)));
    for (let i = 0; i < 4; i++) {
      const tpl = available[Math.min(available.length - 1, start + (i % 3))];
      const itemLevel = Math.max(1, level + (i === 3 ? 1 : 0));
      const item = makeItem(tpl, itemLevel, { classId: player.classId, icon: WEAPON_ICONS[player.classId] });
      item.price = Math.round(item.price * (vendorLevel >= 5 ? 1.18 : 1));
      stock.push(item);
    }
  } else if (type === 'armor') {
    const available = gear.armor.filter(t => {
      const req = RARITY_LEVEL_OFFSET[t.rarity] * 3 + 1;
      return req <= level + 2;
    });
    const start = Math.max(0, Math.min(available.length - 3, Math.floor((level - 1) / 4)));
    for (let i = 0; i < 4; i++) {
      const tpl = available[Math.min(available.length - 1, start + (i % 3))];
      const item = makeItem(tpl, Math.max(1, level + (i === 3 ? 1 : 0)), { classId: player.classId });
      item.price = Math.round(item.price * (vendorLevel >= 5 ? 1.18 : 1));
      stock.push(item);
    }
    stock.push(makeTrinket(TRINKETS[Math.min(TRINKETS.length - 1, Math.floor(level / 3))], level));
  } else {
    for (const key of ['health_potion', 'focus_tonic', 'bomb', 'wardraught']) {
      stock.push({ ...CONSUMABLES[key], consumable: true });
    }
    stock.push(makeTrinket(TRINKETS[Math.min(TRINKETS.length - 1, 1 + Math.floor(level / 5))], level));
  }
  return stock;
}

export function itemSummary(item) {
  if (!item) return '';
  if (item.consumable) return item.desc;
  if (item.type === 'weapon') {
    const el = ELEMENTS[item.element]?.name || 'Physical';
    return `${item.damage} power · ${item.elementPower} ${el.toLowerCase()} · Lv.${item.level}`;
  }
  if (item.type === 'armor') {
    return `+${item.health} vitality · +${item.armor} armor · Lv.${item.level}`;
  }
  const bits = [];
  if (item.power) bits.push(`+${item.power} attack`);
  if (item.crit) bits.push(`+${Math.round(item.crit * 100)}% crit`);
  if (item.elementPower) bits.push(`+${item.elementPower} ${ELEMENTS[item.element]?.name.toLowerCase()}`);
  if (item.health) bits.push(`+${item.health} vitality`);
  return bits.join(' · ');
}

export function xpForLevel(level) {
  return Math.round(110 * Math.pow(level, 1.26));
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

export function hash2(x, z, seed = 1) {
  let h = Math.imul(x | 0, 374761393) + Math.imul(z | 0, 668265263) + Math.imul(seed, 2147483647);
  h = (h ^ (h >>> 13)) * 1274126177;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export function valueNoise(x, z, seed = 1) {
  const xi = Math.floor(x), zi = Math.floor(z);
  const xf = x - xi, zf = z - zi;
  const u = xf * xf * (3 - 2 * xf), v = zf * zf * (3 - 2 * zf);
  const a = hash2(xi, zi, seed), b = hash2(xi + 1, zi, seed);
  const c = hash2(xi, zi + 1, seed), d = hash2(xi + 1, zi + 1, seed);
  return (a * (1 - u) + b * u) * (1 - v) + (c * (1 - u) + d * u) * v;
}

export function fbm(x, z, seed = 1) {
  let value = 0, amp = 0.5, freq = 1;
  for (let i = 0; i < 4; i++) {
    value += valueNoise(x * freq, z * freq, seed + i * 11) * amp;
    freq *= 2.03; amp *= 0.5;
  }
  return value;
}

export function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
export function lerp(a, b, t) { return a + (b - a) * t; }
export function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}
export function distance2(ax, az, bx, bz) { return Math.hypot(ax - bx, az - bz); }

export function formatTime(hours) {
  const h = Math.floor(hours) % 24;
  const m = Math.floor((hours % 1) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

export function pickWeighted(rng, table) {
  const entries = Object.entries(table);
  const total = entries.reduce((sum, [, v]) => sum + v, 0);
  let roll = rng() * total;
  for (const [key, weight] of entries) {
    roll -= weight;
    if (roll <= 0) return key;
  }
  return entries[0][0];
}

import * as THREE from 'three';
import { CLASSES, ELEMENTS, RARITIES } from './data.js';

const skinTones = [0xf0c8a3, 0xd39b74, 0xa96e4f, 0x754737, 0xe7e0d1];
const clothTones = [0x426e70, 0x7b3f45, 0x3f4f83, 0x6b5732, 0x4d5644];
const materialCache = new Map();
const shadowMaterials = new Set();

const _c = new THREE.Color();
const _c2 = new THREE.Color();

export function paletteFromIndices(skin = 0, cloth = 0) {
  return { skin: skinTones[skin % skinTones.length], cloth: clothTones[cloth % clothTones.length] };
}

export function material(color, options = {}) {
  const key = `${color}_${options.emissive || 0}_${options.emissiveIntensity || 0}_${options.roughness || 0}_${options.metalness || 0}_${options.transparent || 0}_${options.opacity || 1}_${options.flat === false ? 0 : 1}`;
  if (!options.unique && materialCache.has(key)) return materialCache.get(key);
  const mat = new THREE.MeshStandardMaterial({
    color,
    roughness: options.roughness ?? 0.86,
    metalness: options.metalness ?? 0.02,
    flatShading: options.flat !== false,
    emissive: options.emissive ?? 0x000000,
    emissiveIntensity: options.emissiveIntensity ?? 0,
    transparent: !!options.transparent,
    opacity: options.opacity ?? 1,
    side: options.side ?? THREE.FrontSide,
    depthWrite: options.depthWrite ?? true,
    vertexColors: !!options.vertexColors,
  });
  if (!options.unique) materialCache.set(key, mat);
  shadowMaterials.add(mat);
  return mat;
}

export function box(w, h, d, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function cone(r, h, segments, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(r, h, segments), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function cylinder(rt, rb, h, segments, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, segments), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function sphere(r, mat, x = 0, y = 0, z = 0, segments = 8, rings = 6) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, segments, rings), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function shade(hex, amount = 0) {
  _c.setHex(hex);
  if (amount > 0) _c.lerp(_c2.setHex(0xffffff), amount);
  else _c.lerp(_c2.setHex(0x000000), -amount);
  return _c.getHex();
}

export function elementColor(element) {
  return ELEMENTS[element]?.color || 0xe7dcc2;
}

export function mixColor(a, b, t) {
  return new THREE.Color(a).lerp(new THREE.Color(b), t).getHex();
}

export function createCharacter(config = {}) {
  const race = config.race || 'human';
  const beastType = config.beastType || 'dog';
  const sex = config.sex || 'feminine';
  const classId = config.classId || 'warrior';
  const cls = CLASSES[classId] || CLASSES.warrior;
  const skin = config.skin ?? skinTones[0];
  const cloth = config.cloth ?? clothTones[0];
  const role = config.role || 'hero';
  const palette = config.palette || null;
  const npc = role === 'npc';
  const mainCloth = palette ? palette[0] : cloth;
  const accent = palette ? palette[1] : mixColor(cloth, 0xe9b85f, 0.45);
  const skinColor = palette ? palette[2] : skin;
  const dark = shade(mainCloth, -0.42);
  const darkCloth = shade(mainCloth, -0.62);
  const leather = role === 'npc' ? shade(accent, -0.35) : 0x3c2a22;
  const clothMat = material(mainCloth);
  const darkMat = material(dark);
  const accentMat = material(accent);
  const skinMat = material(skinColor);
  const leatherMat = material(leather);
  const metalMat = material(0x8b9491, { metalness: 0.65, roughness: 0.4 });
  const goldMat = material(0xd5a44c, { metalness: 0.7, roughness: 0.36, emissive: 0x3a2405, emissiveIntensity: 0.25 });
  const eyeMat = material(race === 'demon' ? 0xff6a4d : 0x101820, { emissive: race === 'demon' ? 0x761106 : 0x000000, emissiveIntensity: race === 'demon' ? 0.8 : 0 });

  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const shoulder = sex === 'masculine' ? 0.67 : 0.58;
  const hip = sex === 'feminine' ? 0.56 : 0.49;
  const torsoH = sex === 'feminine' ? 0.58 : 0.62;

  // hips and torso
  body.add(box(hip, 0.2, 0.31, darkMat, 0, 1.02, 0));
  const torso = box(shoulder, torsoH, 0.34, clothMat, 0, 1.35, 0);
  body.add(torso);
  body.add(box(shoulder * 0.92, 0.1, 0.36, leatherMat, 0, 1.08, 0));
  body.add(box(0.1, 0.1, 0.05, goldMat, 0, 1.09, -0.19));
  body.add(box(shoulder * 0.75, 0.08, 0.36, accentMat, 0, 1.51, 0));

  // neck + head
  const headPivot = new THREE.Group();
  headPivot.position.set(0, 1.71, 0);
  body.add(headPivot);
  headPivot.add(box(0.13, 0.13, 0.13, skinMat, 0, 0.01, 0));
  const head = box(0.39, 0.4, 0.35, skinMat, 0, 0.21, 0);
  headPivot.add(head);
  headPivot.add(box(0.045, 0.055, 0.04, eyeMat, -0.09, 0.23, -0.185));
