    const tail = new THREE.Group(); tail.position.set(0, 0.84, 0.55); root.add(tail);
    const t = cylinder(0.04, 0.14, 0.55, 4, bodyMat, 0, 0.12, 0.2); t.rotation.x = -0.8; tail.add(t); rig.tail = tail;
    for (let i = 0; i < 4; i++) {
