    const chest = box(0.95, 0.9, 0.65, material(0x54412d), 0, 1.55, 0); root.add(chest);
    const head = box(0.72, 0.65, 0.6, material(0x493726), 0, 2.2, 0); root.add(head); rig.head = head;
