    const hood = new THREE.Mesh(new THREE.ConeGeometry(0.4, 0.62, 7, 1, true), material(mixColor(0x232232, ec, 0.2), { transparent: true, opacity: 0.94, side: THREE.DoubleSide }));
    hood.position.y = 1.9; root.add(hood); rig.head = hood;
