  group.add(cylinder(1.24, 1.28, 0.12, 10, material(0x6d6557), 0, 0.78, 0));
  for (const sx of [-0.95, 0.95]) group.add(box(0.13, 2.2, 0.13, material(0x4a3221), sx, 1.72, 0));
