669:   updateEnemyLabels() {
670:     const camera = this.game.camera;
671:     const alive = new Set();
672:     const p = this.game.player;
673:     for (const enemy of this.game.enemies) {
674:       if (enemy.dead || enemy.isBoss) continue;
675:       alive.add(enemy.id);
676:       const distance = enemy.root.position.distanceTo(p.position);
677:       if (distance > 30 || this.game.uiOpen) {
678:         if (this.enemyLabels.has(enemy.id)) this.enemyLabels.get(enemy.id).style.display = 'none';
679:         continue;
680:       }
681:       let label = this.enemyLabels.get(enemy.id);
682:       if (!label) {
683:         label = el('div', 'enemy-label');
684:         label.innerHTML = '<span class="enemy-el"></span><b></b><i><s></s></i>';
685:         $('world-labels').appendChild(label);
686:         this.enemyLabels.set(enemy.id, label);
687:       }
688:       label.style.display = '';
689:       const vec = new THREE.Vector3(enemy.root.position.x, enemy.root.position.y + enemy.height + 0.6, enemy.root.position.z).project(camera);
690:       if (vec.z > 1 || vec.z < -1 || Math.abs(vec.x) > 1.08 || Math.abs(vec.y) > 1.08) { label.style.display = 'none'; continue; }
691:       label.style.left = `${(vec.x * 0.5 + 0.5) * window.innerWidth}px`;
692:       label.style.top = `${(-vec.y * 0.5 + 0.5) * window.innerHeight}px`;
693:       label.querySelector('b').textContent = enemy.name;
694:       label.querySelector('.enemy-el').textContent = ELEMENTS[enemy.element]?.icon || '◆';
695:       label.querySelector('.enemy-el').style.color = ELEMENTS[enemy.element]?.css || '#fff';
696:       label.querySelector('s').style.width = `${Math.max(0, enemy.health / enemy.maxHealth) * 100}%`;
697:       label.classList.toggle('elite', !!enemy.def.elite);
698:     }
699:     for (const [id, label] of this.enemyLabels) {
700:       if (!alive.has(id)) { label.remove(); this.enemyLabels.delete(id); }
701:     }
702:   }
