737:   drawMinimap() {
738:     const canvas = $('minimap');
739:     const ctx = canvas.getContext('2d');
740:     const p = this.game.player;
741:     const size = 196;
742:     ctx.imageSmoothingEnabled = false;
743:     ctx.clearRect(0, 0, size, size);
744:     const range = 92;
745:     const map = this.game.world.mapCanvas;
746:     const mx = p.position.x + WORLD_SIZE / 2;
747:     const mz = p.position.z + WORLD_SIZE / 2;
748:     const sx = mx - range / 2, sy = mz - range / 2;
749:     ctx.fillStyle = '#0b1716'; ctx.fillRect(0, 0, size, size);
750:     ctx.drawImage(map, sx, sy, range, range, 0, 0, size, size);
751:     const toLocal = (x, z) => [((x + WORLD_SIZE / 2 - sx) / range) * size, ((z + WORLD_SIZE / 2 - sy) / range) * size];
752:     for (const chest of this.game.world.chests) {
753:       if (chest.x < sx || chest.x > sx + range || chest.z < sy || chest.z > sy + range) continue;
754:       const [x, y] = toLocal(chest.x, chest.z);
755:       ctx.fillStyle = chest.opened ? '#5d5a4c' : chest.locked ? '#9b84dd' : '#e9b85f';
756:       ctx.fillRect(x - 2, y - 2, 4, 4);
757:     }
758:     for (const npc of this.game.npcs) {
759:       const [x, y] = toLocal(npc.def.pos[0], npc.def.pos[1]);
760:       const quest = npc.def.questId ? this.game.quests[npc.def.questId] : null;
761:       ctx.fillStyle = quest?.ready ? '#71d7c4' : quest?.state === 'available' ? '#e9b85f' : npc.def.vendor ? '#9ad5c9' : '#d8cfb0';
762:       ctx.fillRect(x - 2, y - 2, 4, 4);
763:     }
764:     for (const enemy of this.game.enemies) {
765:       if (enemy.dead || enemy.isBoss) continue;
766:       if (enemy.root.position.x < sx || enemy.root.position.x > sx + range || enemy.root.position.z < sy || enemy.root.position.z > sy + range) continue;
767:       const [x, y] = toLocal(enemy.root.position.x, enemy.root.position.z);
768:       ctx.fillStyle = '#d85a57'; ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
