366:     const points = [new THREE.Vector3(-0.22, 0.5, 0), new THREE.Vector3(0.16, 0.1, 0), new THREE.Vector3(-0.22, -0.3, 0)];
367:     group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), stringMat));
