409: export function animateHumanoid(character, time, speed = 0, attack = 0, dead = false) {
410:   const rig = character.userData?.rig;
411:   if (!rig || !rig.body || !rig.armR || !rig.legL) return;
412:   const moving = Math.min(1, speed / 4.5);
413:   const swing = Math.sin(time * (8 + moving * 4)) * (0.22 + moving * 0.55);
414:   rig.legL.rotation.x = swing * moving;
415:   rig.legR.rotation.x = -swing * moving;
416:   rig.armL.rotation.x = -swing * 0.75 * moving;
417:   rig.armR.rotation.x = swing * 0.75 * moving;
418:   rig.body.position.y = Math.abs(Math.sin(time * (8 + moving * 4))) * 0.035 * moving + Math.sin(time * 2.2) * 0.008;
419: 
420:   if (attack > 0) {
421:     const p = 1 - attack;
422:     const swingAmount = Math.sin(Math.min(1, p * 1.4) * Math.PI);
423:     rig.armR.rotation.x = -1.3 * swingAmount;
424:     rig.armR.rotation.z = -0.8 * swingAmount;
425:     rig.body.rotation.y = -0.26 * swingAmount;
426:   } else {
427:     rig.armR.rotation.z *= 0.86;
428:     rig.body.rotation.y *= 0.85;
429:   }
430:   rig.headPivot.rotation.x = Math.sin(time * 1.1) * 0.025;
431:   if (rig.halo) {
432:     rig.halo.rotation.z = time * 0.45;
433:     rig.halo.position.y = 2.15 + Math.sin(time * 2) * 0.03;
434:   }
435:   if (rig.wings.length) {
436:     const flap = Math.sin(time * 2.4) * 0.05 + 0.08;
437:     rig.wings[0].rotation.z = -flap;
438:     rig.wings[1].rotation.z = flap;
439:     rig.wings[0].rotation.y = 0.1 + Math.sin(time * 1.3) * 0.05;
440:     rig.wings[1].rotation.y = -0.1 - Math.sin(time * 1.3) * 0.05;
441:   }
442:   if (rig.tail) {
443:     rig.tail.rotation.y = Math.sin(time * 2.5) * 0.25;
444:     rig.tail.rotation.x = Math.sin(time * 1.7) * 0.06;
445:   }
446:   if (dead) {
447:     rig.body.rotation.z = Math.min(Math.PI * 0.48, rig.body.rotation.z + 0.04);
448:     rig.body.position.y = 0.1;
449:   }
450: }
