715: export function animateEnemy(root, time, moving = 0, attack = 0) {
716:   const rig = root.userData.rig;
717:   if (!rig) return;
718:   const phase = time * 6 + (rig.idle || 0);
719:   if (rig.legs) {
720:     rig.legs.forEach((leg, i) => {
721:       leg.rotation.x = Math.sin(phase + i * 1.7) * 0.6 * moving;
722:     });
723:   }
724:   if (rig.parts) {
725:     rig.parts.forEach((part, i) => {
726:       if (part.isMesh && i % 2 === 0) part.rotation.y = Math.sin(time * 1.4 + i) * 0.08;
727:       if (part.isGroup) part.rotation.x = Math.sin(phase + i) * 0.15 * moving;
728:     });
729:   }
730:   if (rig.body) {
731:     rig.body.position.y += Math.sin(time * 2 + (rig.idle || 0)) * 0.001;
732:     if (root.userData.model === 'slime') {
733:       rig.body.scale.y = 0.82 + Math.sin(time * 3) * 0.06;
734:       rig.body.scale.x = 1 + Math.cos(time * 3) * 0.035;
735:     }
736:     if (root.userData.model === 'wisp' || root.userData.model === 'wraith') {
737:       rig.body.position.y = (rig.body.userData.baseY ?? rig.body.position.y) + Math.sin(time * 2.2) * 0.06;
738:     }
739:   }
740:   if (rig.wings) {
741:     rig.wings.forEach((wing, i) => {
742:       if (wing.rotation && !wing.isMesh) wing.rotation.z += Math.sin(time * 9 + i) * 0.01;
743:       else if (wing.isMesh) wing.rotation.z = (i % 2 ? -1 : 1) * (0.9 + Math.sin(time * 11) * 0.15);
744:     });
745:   }
746:   if (rig.ring) rig.ring.rotation.z = time * 0.8;
747:   if (rig.aura) {
748:     rig.aura.rotation.z = time * 0.35;
749:     if (rig.aura.material) rig.aura.material.opacity = 0.18 + Math.sin(time * 3) * 0.08;
750:   }
751:   if (rig.tail) rig.tail.rotation.y = Math.sin(time * 4) * 0.35;
752:   if (attack > 0) {
753:     const lunge = Math.sin((1 - attack) * Math.PI);
754:     root.children.forEach(child => {
755:       if (child.userData.baseZ === undefined) child.userData.baseZ = child.position.z;
756:       child.position.z = child.userData.baseZ - lunge * 0.22;
757:     });
758:   }
759: }
