20: function canvasTexture(size, draw, repeat = 1) {
21:   const canvas = document.createElement('canvas');
22:   canvas.width = size; canvas.height = size;
23:   const ctx = canvas.getContext('2d');
24:   ctx.imageSmoothingEnabled = false;
25:   draw(ctx, size);
26:   const tex = new THREE.CanvasTexture(canvas);
27:   tex.magFilter = THREE.NearestFilter;
28:   tex.minFilter = THREE.NearestFilter;
29:   tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
30:   tex.repeat.set(repeat, repeat);
31:   tex.anisotropy = 1;
32:   return tex;
33: }
