38:     const rng = mulberry32(308);
39:     for (let i = 0; i < 90; i++) {
40:       const x = Math.floor(rng() * s), y = Math.floor(rng() * s);
41:       const v = Math.floor(158 + rng() * 84);
42:       ctx.fillStyle = `rgb(${v},${v},${v})`;
43:       ctx.fillRect(x, y, rng() > .8 ? 2 : 1, 1);
44:     }
45:     for (let i = 0; i < 20; i++) {
46:       const x = Math.floor(rng() * s), y = Math.floor(rng() * s);
47:       ctx.fillStyle = 'rgba(48,42,31,.26)';
48:       ctx.fillRect(x, y, 1, 1);
49:     }
50:   }, 58);
