139:   heightAt(x, z) {
140:     let h = 0.15 + fbm(x * 0.019, z * 0.019, 8) * 2.55 + (valueNoise(x * 0.061, z * 0.061, 4) - 0.5) * 0.52;
141:     // Whisperwood shoulders
142:     const forestD = distance2(x, z, BIOMES.forest.center[0], BIOMES.forest.center[1]);
143:     h += smoothstep(55, 12, forestD) * 1.25 + fbm(x * 0.045, z * 0.045, 17) * smoothstep(60, 15, forestD) * 1.4;
144:     // Stormcrag highlands
145:     const highD = distance2(x, z, BIOMES.highlands.center[0], BIOMES.highlands.center[1]);
146:     h += smoothstep(55, 8, highD) * 8.6 + fbm(x * 0.07, z * 0.07, 22) * 2.8 * smoothstep(55, 8, highD);
147:     // Cinderwake volcano
148:     const volD = distance2(x, z, VOLCANO.x, VOLCANO.z);
149:     const cone = Math.max(0, 1 - volD / 62);
150:     h += Math.pow(cone, 1.6) * 15.5;
151:     if (volD < 13) h -= (1 - volD / 13) * 7.6;
152:     h += fbm(x * 0.09, z * 0.09, 31) * 1.5 * cone;
153:     // Mirrormere basin
154:     const lakeD = distance2(x, z, LAKE.x, LAKE.z);
155:     h -= (1 - smoothstep(12, 35, lakeD)) * 4.7;
156:     // Eastern sea shelf
157:     h -= smoothstep(108, 135, x) * 6.5;
158:     h -= smoothstep(112, 135, z) * 2.4;
159:     // Grave terraces
160:     const graveD = distance2(x, z, BIOMES.graveyard.center[0], BIOMES.graveyard.center[1]);
161:     h = lerp(h, 0.7 + fbm(x * 0.06, z * 0.06, 43) * 0.65, (1 - smoothstep(17, 31, graveD)) * 0.8);
162:     // Cave floor, kept level and dark
163:     const caveD = distance2(x, z, CAVE.x, CAVE.z);
164:     h = lerp(h, CAVE.flat + fbm(x * 0.1, z * 0.1, 66) * 0.24, 1 - smoothstep(10, 16, caveD));
165:     // Settlements are level, with soft outskirts
166:     const townD = distance2(x, z, TOWN.x, TOWN.z);
167:     h = lerp(h, TOWN.flat, 1 - smoothstep(21, 29.5, townD));
168:     const cityD = distance2(x, z, CITY.x, CITY.z);
169:     h = lerp(h, CITY.flat, 1 - smoothstep(22, 30.5, cityD));
170:     // Keep the spawn approach flat and readable
171:     if (Math.abs(x) < 9 && z > 25 && z < 43) h = lerp(h, 0.55, 0.7);
