412:         positions[i * 6] = x; positions[i * 6 + 1] = y; positions[i * 6 + 2] = z;
413:         positions[i * 6 + 3] = x + 0.04; positions[i * 6 + 4] = y - 0.65; positions[i * 6 + 5] = z;
414:         speeds[i] = 14 + rng() * 12;
415:       }
416:       const geo = new THREE.BufferGeometry();
417:       geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
418:       const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
419:       const lines = new THREE.LineSegments(geo, mat);
420:       lines.frustumCulled = false;
421:       lines.userData.speeds = speeds;
422:       lines.visible = false;
