208: function fenceLine(world, x1, z1, x2, z2, gap = 0) {
209:   const dx = x2 - x1, dz = z2 - z1;
210:   const length = Math.hypot(dx, dz);
211:   const angle = Math.atan2(dx, dz);
212:   const count = Math.floor(length / 2.2);
213:   const wood = material(0x563d29);
214:   for (let i = 0; i <= count; i++) {
215:     if (gap > 0 && i % gap === 0) continue;
216:     const t = i / count;
217:     const x = x1 + dx * t, z = z1 + dz * t;
218:     const y = world.heightAt(x, z);
219:     const group = new THREE.Group(); group.position.set(x, y, z); group.rotation.y = angle; world.scene.add(group);
220:     group.add(box(0.16, 1.25, 0.16, wood, 0, 0.62, 0));
221:     group.add(box(0.1, 0.1, 2.25, wood, 0, 0.9, 1.1));
222:     group.add(box(0.1, 0.1, 2.25, wood, 0, 0.45, 1.1));
223:   }
224: }
