253: export function buildRoads(world) {
254:   const path = (points, width, color = 0xb9a274) => {
255:     const positions = [];
256:     const indices = [];
257:     for (let i = 0; i < points.length; i++) {
258:       const [x, z] = points[i];
259:       const [nx, nz] = points[Math.min(points.length - 1, i + 1)];
260:       const [px, pz] = points[Math.max(0, i - 1)];
261:       const dx = nx - px, dz = nz - pz;
262:       const len = Math.hypot(dx, dz) || 1;
263:       const ox = (-dz / len) * width / 2, oz = (dx / len) * width / 2;
264:       const y1 = world.heightAt(x + ox, z + oz) + 0.06;
265:       const y2 = world.heightAt(x - ox, z - oz) + 0.06;
266:       positions.push(x + ox, y1, z + oz, x - ox, y2, z - oz);
267:       if (i > 0) {
268:         const a = (i - 1) * 2;
269:         indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
270:       }
271:     }
272:     const geo = new THREE.BufferGeometry();
273:     geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
274:     geo.setIndex(indices);
275:     geo.computeVertexNormals();
276:     const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color, roughness: 1, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 }));
277:     mesh.receiveShadow = true;
278:     world.scene.add(mesh);
279:   };
280:   path([[0, 40], [0, 33], [0, 24], [4, 19], [11, 16], [20, 18], [30, 21], [41, 23], [50, 26], [56, 29]], 4.4);
281:   path([[0, 10], [-7, 5], [-15, -3], [-24, -15], [-35, -28], [-41, -42], [-30, -52]], 3.1, 0xa99669);
282:   path([[58, 29], [67, 35], [78, 40], [90, 46], [101, 53]], 3.6);
283:   path([[-41, -42], [-58, -48], [-69, -57]], 2.4, 0x877b60);
284: }
