  house(world, { x: -2.2, z: -3.6, w: 8.3, d: 6.4, h: 3.2, floors: 2, wall: 0xc8c0a6, roof: 0x42514f, trim: 0x3f3b33, rot: 0.02, shopSign: 'LANTERN CHAPEL' });
