    makeVentTrap(-66, 44, 4, 'ice'),
    makeVentTrap(88, -71, 6, 'lightning'),
  );
  // A trapped path through Gloomroot's entrance.
  world.traps.push(makeSpikeTrap(72, -35, 5));
}

