+    game.scene.add(this.root);
+    this.height = Math.max(
+      1.1,
+      (this.def.height || (this.isBoss ? 2.2 : 1.35)) * (this.isBoss ? 1.35 : 1) * Math.min(1.7, this.def.scale || 1),
