export function watchProject(root, changed) {
  const watchers = new Map()
  let timer
  const scan = directory => {
    try {
      if (!watchers.has(directory)) watchers.set(directory, watch(directory, () => {
        clearTimeout(timer)
        timer = setTimeout(() => { scan(directory); changed() }, 250)
